{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 AI Stem Splitter by Oliver Tkach - Version 2.0\par}
{\pard \ql \f0 \sa180 \li0 \fi0 A ReaScript for REAPER that uses Demucs to split audio into high-fidelity stems directly in your project.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 6 stems: vocals, drums, bass, guitar, piano, other\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Quality profiles: fast, balanced, high\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Two-stem mode (target + no_target)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab BPM/key/Hz analysis and project tempo sync\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Automatic track naming, foldering, and colors\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Local processing (no cloud upload)\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 System Requirements\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Python 3.10+\line Windows users should enable "Add Python to PATH" during install.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab FFmpeg\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab Windows: {\f1 winget install Gyan.FFmpeg}\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab macOS: {\f1 brew install ffmpeg}\sa180\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Python dependencies\line {\f1 pip install demucs soundfile==0.12.1 librosa numpy scipy torchcodec}\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Installation and Usage (Manual)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Download your preferred script:\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab {\f1 AI Stem Splitter by Oliver Tkach - GUI.lua} (recommended)\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab {\f1 AI Stem Splitter by Oliver Tkach.lua}\sa180\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab In REAPER, open Action List -> New Action -> Load ReaScript.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Select an audio item and run the script.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 4.\tx360\tab First run may download model files.\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 ReaPack Installation (Recommended)\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Use ReaPack to install and keep scripts updated from this repo.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab In REAPER, open {\f1 Extensions > ReaPack > Import repositories...}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Add: {\f1 https://raw.githubusercontent.com/tkacholiver/aistemsplitter/main/index.xml}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Open {\f1 Extensions > ReaPack > Browse packages}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 4.\tx360\tab Search for {\f1 AI Stem Splitter by Oliver Tkach - GUI.lua}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 5.\tx360\tab Install and click {\f1 Apply}\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Known-good fallback index:\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\f1 https://raw.githubusercontent.com/tkacholiver/aistemsplitter/reapack-working-2026-02-24/index.xml}\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Power User Options\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Device: auto, cpu, cuda, mps\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Segment size tuning for low RAM/VRAM systems\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Worker job count tuning\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Troubleshooting\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Python not found: reinstall Python and enable PATH integration\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Out-of-memory: lower segment seconds\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab FFmpeg missing: install and restart REAPER\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Support\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Instagram: https://www.instagram.com/olivertkachmusic\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab YouTube: https://www.youtube.com/@olivertkachreactions\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Donate: https://tecito.app/olivertkachmusic\sa180\par}
}
